export function TranslatableMessage({ message }) {
  return (
    <AiTranslate
      text={message.body}
      sourceLanguage={message.language}
      author={{ name: message.author.name, role: message.author.title, avatar: message.author.avatarUrl }}
      timestamp={message.sentAtLabel}
      model={{ name: "Claude Haiku 5.5" }}
      translate={async function* ({ text, from, to, signal }) {
        const response = await fetch("/api/translate", { method: "POST", body: JSON.stringify({ text, from, to }), signal });
        if (!response.ok || !response.body) throw new Error("The translation service is unavailable.");
        const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
        while (true) {
          const { value, done } = await reader.read();
          if (done) return;
          yield value;
        }
      }}
      onValueChange={language => savePreferredLanguage(language)}
    />
  );
}

