import { DictationError, type DictationRecognizer } from "@/components/arc/dictation-button/dictation-button";

export const deepgram: DictationRecognizer = async (handlers, signal) => {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true }).catch(() => { throw new DictationError("not-allowed"); });
  const socket = new WebSocket("wss://your-proxy.example.com/listen");
  socket.onmessage = event => {
    const { final, interim, level } = JSON.parse(event.data);
    handlers.onTranscript({ final, interim });
    handlers.onLevel(level);
  };
  signal.addEventListener("abort", () => { socket.close(); stream.getTracks().forEach(t => t.stop()); });
  // ...pipe stream audio into the socket...
  return { stop: () => new Promise(resolve => { socket.onclose = () => resolve(lastFinal); socket.send("finalize"); }) };
};

